package io.github.jasper.monitoring.api.management.model;
public class SecurityEventSummary { private final String id,systemScope,actionCode,status; private final long occurredAt; public SecurityEventSummary(String id,String scope,String action,String status,long occurredAt){this.id=id;this.systemScope=scope;this.actionCode=action;this.status=status;this.occurredAt=occurredAt;} public String getId(){return id;} public String getSystemScope(){return systemScope;} public String getActionCode(){return actionCode;} public String getStatus(){return status;} public long getOccurredAt(){return occurredAt;} }
